package com.middleproject.reminder; import com.middleproject.reminder.domain.ReminderStatus; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class ReminderStatusTest { @Test void validTransitions(){assertTrue(ReminderStatus.CREATED.canTransitionTo(ReminderStatus.SCHEDULE_PENDING));assertTrue(ReminderStatus.SCHEDULE_PENDING.canTransitionTo(ReminderStatus.SCHEDULED));assertTrue(ReminderStatus.SCHEDULED.canTransitionTo(ReminderStatus.DISPATCHED));assertTrue(ReminderStatus.DISPATCHED.canTransitionTo(ReminderStatus.DELIVERED));assertTrue(ReminderStatus.DELIVERED.canTransitionTo(ReminderStatus.ACKNOWLEDGED));assertTrue(ReminderStatus.DELIVERY_FAILED.canTransitionTo(ReminderStatus.RETRYING));} @Test void invalidTransitions(){assertFalse(ReminderStatus.CREATED.canTransitionTo(ReminderStatus.DELIVERED));assertFalse(ReminderStatus.ACKNOWLEDGED.canTransitionTo(ReminderStatus.CREATED));}}
